typedef unsigned int render_flavor_t;

struct nglMesh;
typedef float nglMatrix[4][4];

struct vector4d
{
  float x, y, z, w;
};

struct matrix4x4
{
  vector4d x __attribute__((aligned(16)));
  vector4d y;
  vector4d z;
  vector4d w;
};

static inline matrix4x4 operator*( const matrix4x4& a, const matrix4x4& b )
{
  matrix4x4 local;
  asm("lqc2    vf1,0x0(%2)  \n"
      "lqc2    vf2,0x10(%2) \n"
      "lqc2    vf3,0x20(%2) \n"
      "lqc2    vf4,0x30(%2) \n"
      "lqc2    vf5,0x0(%1) \n"
      "lqc2    vf6,0x10(%1) \n"
      "lqc2    vf7,0x20(%1) \n"
      "lqc2    vf8,0x30(%1) \n"
      "vmulax.xyzw ACC, vf1,vf5 \n"
      "vmadday.xyzw ACC, vf2,vf5 \n"
      "vmaddaz.xyzw ACC, vf3,vf5 \n"
      "vmaddw.xyzw vf9, vf4,vf5 \n"
      "vmulax.xyzw ACC, vf1,vf6 \n"
      "vmadday.xyzw ACC, vf2,vf6 \n"
      "vmaddaz.xyzw ACC, vf3,vf6 \n"
      "vmaddw.xyzw vf10, vf4,vf6 \n"
      "vmulax.xyzw ACC, vf1,vf7 \n"
      "vmadday.xyzw ACC, vf2,vf7 \n"
      "vmaddaz.xyzw ACC, vf3,vf7 \n"
      "vmaddw.xyzw vf11, vf4,vf7 \n"
      "vmulax.xyzw ACC, vf1,vf8 \n"
      "vmadday.xyzw ACC, vf2,vf8 \n"
      "vmaddaz.xyzw ACC, vf3,vf8 \n"
      "vmaddw.xyzw vf12, vf4,vf8 \n"
      "sqc2    vf9,0x0(%0) \n"
      "sqc2    vf10,0x10(%0) \n"
      "sqc2    vf11,0x20(%0) \n"
      "sqc2    vf12,0x30(%0) \n"
    :
    : "r" (&local), "r" (&a), "r" (&b)
  );
  return local;
}

struct po
{
  matrix4x4 matrix;
  const matrix4x4& get_matrix() const { return matrix; }
};

union color32
{
  struct { unsigned char r, g, b, a; } c;
  unsigned int value;
};

class instance_render_info
{
public:
  float number_of_faces_to_attempt;
  char alignment[12];
  po local_to_world;
  unsigned int force_flags;
  color32 color_scale;
  float camera_relative_rotation;
  char frame_time_info[12];
  void* my_region;
  float particle_scale;
  void* my_light_set;
  void* alt_materials;
  int frame;
  float render_scale[3];

  const po& get_local_to_world() const { return local_to_world; }
  const color32& get_color_scale() const { return color_scale; }
};

struct nglRenderParams
{
  unsigned int Flags;
  char pad[12];
  float TintColor[4];
  float Scale[3];
  char tail[36];
};

enum
{
  NGLP_TINT = 1,
  NGLP_SCALE = 0x40,
  NGLP_REVERSE_BACKFACECULL = 0x80,
  NGLMTX_VIEW_TO_SCREEN = 1,
  RENDER_ENTITY_WIDGET = 0x40
};

extern "C" void nglGetMatrix(nglMatrix&, unsigned int)
  __asm__("nglGetMatrix__FR9nglMatrixUi");
extern "C" void nglListAddMesh(nglMesh*, const nglMatrix&, nglRenderParams*)
  __asm__("nglListAddMesh__FP7nglMeshRC9nglMatrixP15nglRenderParams");
__asm__(".equ nglGetMatrix__FR9nglMatrixUi,0x00399370");
__asm__(".equ nglListAddMesh__FP7nglMeshRC9nglMatrixP15nglRenderParams,0x003A5818");

static inline const nglMatrix& native_to_ngl(const po& p)
{
  return *(const nglMatrix*)&p;
}

static inline const nglMatrix& native_to_ngl(const matrix4x4& m)
{
  return *(const nglMatrix*)&m;
}

static int _nglRenderInstanceInfo( nglMesh* mesh, instance_render_info* iri, int num, render_flavor_t flavor )
{
  for( int i = 0; i < num; i++ ) {
    const po& p = iri[i].get_local_to_world( );
    const color32& c = iri[i].get_color_scale( );
    const float s = iri[i].particle_scale;

    nglRenderParams params;
    params.Flags = 0;

    if ( c.c.a != 255 )
    {
      params.Flags |= NGLP_TINT;
      params.TintColor[0] = 1.0f;
      params.TintColor[1] = 1.0f;
      params.TintColor[2] = 1.0f;
      params.TintColor[3] = ( ( (float) c.c.a ) / 255.0f );
    }

    if ( s != 1.0f )
    {
      params.Flags |= NGLP_SCALE;
      params.Scale[0] = s;
      params.Scale[1] = s;
      params.Scale[2] = s;
      if (s < 0)
        params.Flags ^= NGLP_REVERSE_BACKFACECULL;
    }

    if ( flavor & RENDER_ENTITY_WIDGET )
    {
      nglMatrix view_to_screen;
      nglGetMatrix( view_to_screen, NGLMTX_VIEW_TO_SCREEN );
      matrix4x4 &fp = *(matrix4x4 *)&p;
      matrix4x4 vs = *(matrix4x4 *)&view_to_screen;
      matrix4x4 the_xform = fp * vs;
      nglListAddMesh( mesh, native_to_ngl( the_xform ), &params);
    }
    else
      nglListAddMesh( mesh, native_to_ngl( p.get_matrix( ) ), &params );
  }

  return 0;
}
